shaders.vertex:
#version 300 es

uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
uniform 	mediump vec4 _Color;
in highp vec4 in_POSITION0;
in highp vec4 in_COLOR0;
in highp vec2 in_TEXCOORD0;
out mediump vec4 vs_COLOR0;
out mediump vec2 vs_TEXCOORD0;
out highp vec4 vs_TEXCOORD1;
vec4 u_xlat0;
vec4 u_xlat1;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    u_xlat0 = in_COLOR0 * _Color;
    vs_COLOR0 = u_xlat0;
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy;
    vs_TEXCOORD1 = in_POSITION0;
    return;
}

shaders.fragment:
#version 300 es

precision highp int;
uniform 	vec4 _Time;
uniform 	vec4 _ClipRect;
uniform 	vec4 _MainSpeed;
uniform 	vec4 _DisturbAmount;
uniform 	vec4 _DisturbMap_ST;
uniform 	vec4 _DissolveSpeed;
uniform 	vec4 _DissolveMapA_ST;
uniform 	vec4 _DissolveMapB_ST;
uniform lowp sampler2D _DisturbMap;
uniform lowp sampler2D _MainTex;
uniform lowp sampler2D _DissolveMapA;
uniform lowp sampler2D _DissolveMapB;
in mediump vec4 vs_COLOR0;
in mediump vec2 vs_TEXCOORD0;
in highp vec4 vs_TEXCOORD1;
layout(location = 0) out mediump vec4 SV_Target0;
vec2 u_xlat0;
mediump float u_xlat16_0;
lowp float u_xlat10_0;
vec4 u_xlat1;
mediump vec4 u_xlat16_1;
vec2 u_xlat2;
bvec2 u_xlatb2;
vec2 u_xlat3;
lowp float u_xlat10_3;
bvec2 u_xlatb3;
vec2 u_xlat6;
void main()
{
    u_xlat0.xy = vs_TEXCOORD0.xy * _DissolveMapA_ST.xy + _DissolveMapA_ST.zw;
    u_xlat0.xy = _Time.yy * _DissolveSpeed.xy + u_xlat0.xy;
    u_xlat10_0 = texture(_DissolveMapA, u_xlat0.xy).x;
    u_xlat3.xy = vs_TEXCOORD0.xy * _DissolveMapB_ST.xy + _DissolveMapB_ST.zw;
    u_xlat3.xy = _Time.yy * _DissolveSpeed.zw + u_xlat3.xy;
    u_xlat10_3 = texture(_DissolveMapB, u_xlat3.xy).x;
    u_xlat16_0 = u_xlat10_3 * u_xlat10_0;
    u_xlat3.xy = vs_TEXCOORD0.xy * _DisturbMap_ST.xy + _DisturbMap_ST.zw;
    u_xlat16_1 = vs_COLOR0.yyxx + vs_COLOR0.yyxx;
    u_xlat1 = u_xlat16_1 * _DisturbAmount;
    u_xlat3.xy = _Time.yy * u_xlat1.xy + u_xlat3.xy;
    u_xlat10_3 = texture(_DisturbMap, u_xlat3.xy).x;
    u_xlat6.xy = _Time.yy * _MainSpeed.xy + vs_TEXCOORD0.xy;
    u_xlat2.xy = (-u_xlat6.xy) + vec2(u_xlat10_3);
    u_xlat3.xy = u_xlat1.zw * u_xlat2.xy + u_xlat6.xy;
    u_xlat1 = texture(_MainTex, u_xlat3.xy);
    u_xlat0.x = u_xlat16_0 * u_xlat1.w;
    u_xlat0.x = u_xlat0.x * vs_COLOR0.w;
    u_xlatb3.xy = greaterThanEqual(vs_TEXCOORD1.xyxx, _ClipRect.xyxx).xy;
    u_xlat3.xy = mix(vec2(0.0, 0.0), vec2(1.0, 1.0), vec2(u_xlatb3.xy));
    u_xlatb2.xy = greaterThanEqual(_ClipRect.zwzz, vs_TEXCOORD1.xyxx).xy;
    u_xlat2.xy = mix(vec2(0.0, 0.0), vec2(1.0, 1.0), vec2(u_xlatb2.xy));
    u_xlat3.xy = u_xlat3.xy * u_xlat2.xy;
    u_xlat3.x = u_xlat3.y * u_xlat3.x;
    u_xlat1.w = u_xlat3.x * u_xlat0.x;
    SV_Target0 = u_xlat1;
    return;
}
